// 1. By value (default, safest for primitives)
PcoThread t1(myTask, 42);

// 2. By pointer (watch object lifetime!)
Type1 a1;
PcoThread t2(myTaskPtr, &a1);

// 3. By reference (MUST wrap in std::ref)
Type1 a2;
PcoThread t3(myTaskRef, std::ref(a2));

// 4. Instance method on an object
SomeClass* obj = new SomeClass();
PcoThread t4(&SomeClass::someFunction, obj, 10);

// 5. Instance method from inside the class itself
PcoThread t5(&SomeClass::someFunction, this, 10);
